/** Starter factory definitions by name, as YAML text. */
export const STARTERS: Readonly<Record<string, string>> = {
  "build-swamp-extension":
    'schemaVersion: 1\nname: build-swamp-extension\ndescription: |-\n  Build a swamp extension from plan to release: plan it, have the plan\n  reviewed, implement it, check it, have the change reviewed, and release it.\n  build-swamp-extension.md, beside this factory definition, walks one work item\n  through it from start to done.\n\n  For: a developer building their own swamp extension. For other code, start\n  from starter.yaml.\n\n  Change first: the release route your repository uses (below), and the\n  skills the plan-review and code-review stages load.\n\n  It releases one of two ways. registry-push: `swamp extension push`\n  publishes the extension. pull-request: a pull request is merged and CI\n  publishes it; a repository that verifies before a pull request opens (as\n  swamp-extensions does) records the attestation id.\n\n  People decide at four points: approving the plan, waiving the quality score,\n  releasing, and abandoning the work. A person can also always send the work\n  back by hand (revise, recheck), so declining an approval never leaves\n  abandon as the only way out. Every check and the release are bound to the\n  commit named in change-summary, which is the commit that was reviewed.\n  Commits are full 40-character SHAs, so the same commit always compares\n  equal.\n\n  The CEL vocabulary in bindings and cel gates is defined in\n  extensions/models/_lib/engine/cel_context.ts. This factory definition relies\n  on one rule of it: in CEL, evidence["x"] is the latest record of x in the era\n  from any stage, unlike the evidence-recorded gate, which only accepts evidence\n  from the current stage and cycle. implement.submit depends on it.\n\nstages:\n  - id: plan\n    initial: true\n    projection: { status: triaged }\n    description: Plan the change to the extension.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Plan the change. Name the files each step touches, how it will be\n        tested, and whether the manifest version needs a bump (any behaviour\n        change to a published extension does).\n    artifacts:\n      - name: plan\n        schema:\n          type: object\n          required: [summary, steps, testingStrategy, versionBump]\n          properties:\n            summary: { type: string, minLength: 1 }\n            steps:\n              type: array\n              minItems: 1\n              items:\n                type: object\n                required: [description, files]\n                additionalProperties: false\n                properties:\n                  description: { type: string, minLength: 1 }\n                  files: { type: array, items: { type: string, minLength: 1 } }\n            testingStrategy: { type: string, minLength: 1 }\n            versionBump:\n              type: object\n              required: [needed, reason]\n              additionalProperties: false\n              properties:\n                needed: { type: boolean }\n                reason: { type: string, minLength: 1 }\n    transitions:\n      - name: submit\n        to: plan-review\n        gates:\n          - type: artifact-exists\n            config: { artifact: plan }\n\n  - id: plan-review\n    projection: { status: triaged }\n    description: >-\n      Adversarial review of the current plan. Approval needs a fresh review\n      with no open critical or high findings and a person\'s sign-off; open\n      critical or high findings send the plan back. Approving carries the open\n      medium and low findings into implement, which receives plan-review;\n      revise is for when the person wants the plan itself changed and\n      reviewed again.\n    work:\n      mode: dispatch\n      systemPrompt: |\n        You are an adversarial reviewer. Try to refute this plan:\n        {{planSummary}}\n        Check its steps against the code, its testing strategy against the\n        risks, and whether the version bump call is right.\n        Rate a finding critical or high only if the plan would ship a\n        defect, lose data, break a stated rule, or make the declared checks\n        meaningless. Gaps in process, logistics or manual verification that\n        the automated checks already cover are medium at most. Judge the\n        plan against the size of the change: do not ask for verification\n        machinery bigger than the change, and give the smallest adequate fix\n        for each finding. Report findings with severities, and do not soften\n        the severity of a real defect.\n      bindings:\n        planSummary: artifacts["plan"].payload.summary\n      context:\n        inject: [plan]\n    artifacts:\n      - name: plan-review\n        kind: findings\n        reviews: plan\n    transitions:\n      - name: approve\n        to: implement\n        gates:\n          - type: artifact-fresh\n            config: { artifact: plan-review, recordedThisCycle: true }\n          - type: findings-clear\n            config: { artifact: plan-review, blocking: [critical, high] }\n          - type: human-approval\n            config: { id: plan-approval }\n      - name: rework\n        to: plan\n        gates:\n          - type: artifact-fresh\n            config: { artifact: plan-review, recordedThisCycle: true }\n          - type: cel\n            config:\n              expr: >-\n                "plan-review" in artifacts &&\n                artifacts["plan-review"].payload.findings.exists(f,\n                (f.severity == "critical" || f.severity == "high") &&\n                !(has(f.resolved) && f.resolved))\n              message: rework needs an open critical or high finding\n      - name: revise\n        to: plan\n        manual: true\n        description: >-\n          A person declined the plan without a blocking finding, to change\n          the plan itself and have it reviewed again. To act on non-blocking\n          findings during implement, approve instead. Manual, so it never\n          fires on its own.\n\n  - id: implement\n    projection: { status: in_progress }\n    description: Implement the approved plan and commit it.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Implement the approved plan. Commit the work, then record\n        change-summary with the full SHA of the commit you want checked and\n        reviewed. After rework, record it again for the new commit.\n      context:\n        inject: [plan, plan-review]\n    artifacts:\n      - name: change-summary\n        schema:\n          type: object\n          required: [summary, commit, files]\n          properties:\n            summary: { type: string, minLength: 1 }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            files: { type: array, minItems: 1, items: { type: string } }\n            manifestVersion:\n              type: string\n              pattern: "^[0-9]{4}\\\\.[0-9]{2}\\\\.[0-9]{2}\\\\.[0-9]+$"\n    transitions:\n      - name: submit\n        to: check\n        gates:\n          - type: artifact-exists\n            config: { artifact: change-summary }\n          - type: cel\n            config:\n              expr: >-\n                !("checks" in evidence) ||\n                evidence["checks"].payload.commit !=\n                artifacts["change-summary"].payload.commit\n              message: >-\n                change-summary still names the commit already checked; record\n                it for the new commit\n      - name: recheck\n        to: check\n        manual: true\n        description: >-\n          Check the same commit again, for a failure that was not the code\'s\n          (a flaky test, a broken tool). A person decides.\n\n  - id: check\n    projection: { status: in_progress }\n    description: >-\n      Run the extension\'s checks (swamp extension fmt, type check, lint,\n      tests) and swamp extension quality on the change-summary commit. An\n      extension with no manifest yet cannot be scored; a person can waive the\n      quality score instead. If the waiver is granted while a recorded quality\n      score also failed, both passed-with-quality-waiver and quality-failed\n      are satisfied, and the driver asks which to take. When checks and\n      quality both fail, failed and quality-failed are both satisfied; both\n      return to implement.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Check commit {{commit}}. Run swamp extension fmt, the type check,\n        lint and tests, and record checks. Then run\n        swamp extension quality --json and record quality from its output,\n        adding the commit it scored.\n        If the extension has no manifest yet, record checks and ask for the\n        quality waiver instead.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n    evidence:\n      - name: checks\n        schema:\n          type: object\n          required: [commit, status, results]\n          properties:\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            status: { enum: [passed, failed] }\n            results:\n              type: array\n              minItems: 1\n              items:\n                type: object\n                required: [name, status]\n                additionalProperties: false\n                properties:\n                  name: { type: string, minLength: 1 }\n                  status: { enum: [passed, failed, skipped] }\n                  detail: { type: string }\n          $comment: An overall pass cannot contain a failed result.\n          if:\n            properties: { status: { const: passed } }\n          then:\n            properties:\n              results:\n                not:\n                  contains:\n                    properties: { status: { const: failed } }\n      - name: quality\n        description: >-\n          The output of swamp extension quality --json, plus the commit it\n          scored. Only the stable top-level fields are named; the rest is kept\n          as recorded.\n        schema:\n          type: object\n          required: [commit, status, allPassed]\n          properties:\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            status: { type: string, minLength: 1 }\n            allPassed: { type: boolean }\n            rubricVersion: { type: integer }\n            earnedPoints: { type: integer, minimum: 0 }\n            maxClientEarnablePoints: { type: integer, minimum: 0 }\n            percentage: { type: number, minimum: 0, maximum: 100 }\n            factors:\n              type: array\n              items:\n                type: object\n                required: [id, status]\n                properties:\n                  id: { type: string, minLength: 1 }\n                  status: { type: string, minLength: 1 }\n    transitions:\n      - name: passed\n        to: code-review\n        gates:\n          - type: evidence-recorded\n            config: { name: checks, requireField: { status: passed } }\n          - type: evidence-recorded\n            config: { name: quality, requireField: { allPassed: true } }\n          - type: cel\n            config:\n              expr: >-\n                evidence["checks"].payload.commit ==\n                artifacts["change-summary"].payload.commit &&\n                "quality" in evidence &&\n                evidence["quality"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: >-\n                checks and quality must be for the change-summary commit\n      - name: passed-with-quality-waiver\n        to: code-review\n        gates:\n          - type: evidence-recorded\n            config: { name: checks, requireField: { status: passed } }\n          - type: human-approval\n            config: { id: quality-waiver }\n          - type: cel\n            config:\n              expr: >-\n                evidence["checks"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: checks must be for the change-summary commit\n      - name: failed\n        to: implement\n        gates:\n          - type: evidence-recorded\n            config: { name: checks, requireField: { status: failed } }\n      - name: quality-failed\n        to: implement\n        gates:\n          - type: evidence-recorded\n            config: { name: quality, requireField: { allPassed: false } }\n\n  - id: code-review\n    projection: { status: in_progress }\n    description: >-\n      Adversarial review of the checked change. Releasing needs a fresh review\n      with no open critical or high findings and a person\'s approval; open\n      critical or high findings send the change back.\n    work:\n      mode: dispatch\n      systemPrompt: |\n        You are an adversarial reviewer. Review commit {{commit}}:\n        {{changeSummary}}\n        Check it against the approved plan.\n        Rate a finding critical or high only if the change would ship a\n        defect, lose data, break a stated rule, or make the declared checks\n        meaningless. Gaps in process, logistics or manual verification that\n        the automated checks already cover are medium at most. Judge the\n        change against the size of the change: do not ask for verification\n        machinery bigger than the change, and give the smallest adequate fix\n        for each finding. Report findings with severities, and do not soften\n        the severity of a real defect.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n        changeSummary: artifacts["change-summary"].payload.summary\n      context:\n        inject: [plan, change-summary, checks]\n    artifacts:\n      - name: code-review\n        kind: findings\n        reviews: change-summary\n    transitions:\n      - name: accept\n        to: release\n        gates:\n          - type: artifact-fresh\n            config: { artifact: code-review, recordedThisCycle: true }\n          - type: findings-clear\n            config: { artifact: code-review, blocking: [critical, high] }\n          - type: human-approval\n            config: { id: release-approval }\n      - name: rework\n        to: implement\n        gates:\n          - type: artifact-fresh\n            config: { artifact: code-review, recordedThisCycle: true }\n          - type: cel\n            config:\n              expr: >-\n                "code-review" in artifacts &&\n                artifacts["code-review"].payload.findings.exists(f,\n                (f.severity == "critical" || f.severity == "high") &&\n                !(has(f.resolved) && f.resolved))\n              message: rework needs an open critical or high finding\n      - name: revise\n        to: implement\n        manual: true\n        description: >-\n          A person declined the release without a blocking finding; change the\n          work. Manual, so it never fires on its own.\n\n  - id: release\n    projection: { status: in_progress }\n    description: >-\n      Release the reviewed commit: swamp extension push, or a pull request\n      that CI publishes when it merges. commit is the reviewed head that\n      shipped; the merge\'s own commit goes in mergeCommit, which a\n      pull-request release must record, so it cannot be recorded before the\n      merge. A registry push must publish the manifestVersion recorded in\n      change-summary.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Release commit {{commit}}. Either run swamp extension push and record\n        the version it published, or open a pull request (after posting the\n        verification attestation, where the repository requires one) and\n        record the release with its merge commit once it merges.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n    evidence:\n      - name: release\n        schema:\n          type: object\n          required: [via, commit, url]\n          properties:\n            via: { enum: [registry-push, pull-request] }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            mergeCommit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            url: { type: string, format: uri }\n            version:\n              type: string\n              pattern: "^[0-9]{4}\\\\.[0-9]{2}\\\\.[0-9]{2}\\\\.[0-9]+$"\n            pullRequest: { type: string, format: uri }\n            attestationId: { type: string, minLength: 1 }\n          allOf:\n            - if:\n                properties: { via: { const: registry-push } }\n              then:\n                required: [version]\n            - if:\n                properties: { via: { const: pull-request } }\n              then:\n                required: [pullRequest, attestationId, mergeCommit]\n    transitions:\n      - name: released\n        to: done\n        gates:\n          - type: evidence-recorded\n            config: { name: release }\n          - type: cel\n            config:\n              expr: >-\n                evidence["release"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: the release must ship the reviewed commit\n          - type: cel\n            config:\n              expr: >-\n                evidence["release"].payload.via != "registry-push" ||\n                ("manifestVersion" in artifacts["change-summary"].payload &&\n                evidence["release"].payload.version ==\n                artifacts["change-summary"].payload.manifestVersion)\n              message: >-\n                a registry push must publish the manifestVersion recorded in\n                change-summary\n      - name: rework\n        to: implement\n        manual: true\n        description: The release was blocked; go back and change the work.\n\n  - id: done\n    terminal: true\n    projection: { status: shipped }\n\n  - id: abandoned\n    terminal: true\n    projection: { status: closed }\n\nglobalTransitions:\n  - name: abandon\n    to: abandoned\n    gates:\n      - type: human-approval\n        config: { id: abandon-confirmation }\n',
  "minimal":
    "schemaVersion: 1\nname: minimal\ndescription: |-\n  The smallest useful factory definition: one stage of work, then done.\n\n  For: a first look at gatorwalk-factory. Start a work item, record the\n  summary, advance, and the item is done. It has no reviews, approvals or\n  tracker projection; see starter.yaml for a full process.\n\n  Change first: the work stage's description (what the work is), and the\n  summary artifact's schema (what a finished piece of work records).\nstages:\n  - id: work\n    initial: true\n    description: Do the work and summarize it.\n    work:\n      mode: interactive\n    artifacts:\n      - name: summary\n        schema:\n          type: object\n          required: [text]\n          properties:\n            text: { type: string, minLength: 1 }\n    transitions:\n      - name: finish\n        to: done\n        gates:\n          - type: artifact-exists\n            config: { artifact: summary }\n  - id: done\n    terminal: true\n",
  "starter":
    'schemaVersion: 1\nname: starter\ndescription: |-\n  A general software change, from plan to release: plan, review the plan,\n  implement, verify, review the change, release.\n\n  For: changes to any codebase. A person approves the plan and the release,\n  and confirms abandoning the work. A review with a blocking finding, or a\n  failed verify, sends the work back. Every check and the release are bound\n  to the commit named in change-summary. Stages project Lab statuses, so a\n  work item can drive a swamp-club issue; drop the projection keys if it will\n  not. For a swamp extension, build-swamp-extension.yaml adds a quality score\n  and a manifest version check.\n\n  Change first: verify\'s command (your project\'s checks), the skills the\n  plan-review and code-review stages load, and release\'s description (how\n  your project ships).\n\nstages:\n  - id: plan\n    initial: true\n    projection: { status: triaged }\n    description: Plan the change.\n    work:\n      mode: interactive\n      skills: []\n      systemPrompt: |\n        Plan the change with the person. Read the code it touches first.\n        Record plan with a summary, the steps in order (each naming the files\n        it touches) and the testing strategy. After a review sends the plan\n        back, read the findings and record the plan again.\n    artifacts:\n      - name: plan\n        schema:\n          type: object\n          required: [summary, steps, testingStrategy]\n          properties:\n            summary: { type: string, minLength: 1 }\n            steps:\n              type: array\n              minItems: 1\n              items:\n                type: object\n                required: [description, files]\n                additionalProperties: false\n                properties:\n                  description: { type: string, minLength: 1 }\n                  files: { type: array, items: { type: string, minLength: 1 } }\n            testingStrategy: { type: string, minLength: 1 }\n    transitions:\n      - name: submit\n        to: plan-review\n        gates:\n          - type: artifact-exists\n            config: { artifact: plan }\n\n  - id: plan-review\n    projection: { status: triaged }\n    description: >-\n      Adversarial review of the current plan. Open blocking findings send it\n      back; none lets it through. With nothing blocking, approving carries the\n      open medium and low findings into implement, which receives\n      plan-review; revise is for when the person wants the plan itself\n      changed and reviewed again.\n    work:\n      mode: dispatch\n      skills: [adversarial-review]\n      systemPrompt: |\n        You are an adversarial reviewer. Try to refute this plan:\n        {{planSummary}}\n        Check its steps against the code and its testing strategy against the\n        risks.\n        Rate a finding critical or high only if the plan would ship a\n        defect, lose data, break a stated rule, or make the declared checks\n        meaningless. Gaps in process, logistics or manual verification that\n        the automated checks already cover are medium at most. Judge the\n        plan against the size of the change: do not ask for verification\n        machinery bigger than the change, and give the smallest adequate fix\n        for each finding. Report findings with severities, and do not soften\n        the severity of a real defect.\n      bindings:\n        planSummary: artifacts["plan"].payload.summary\n      context:\n        inject: [plan]\n    artifacts:\n      - name: plan-review\n        kind: findings\n        reviews: plan\n    transitions:\n      - name: approve\n        to: implement\n        gates:\n          - type: artifact-fresh\n            config: { artifact: plan-review, recordedThisCycle: true }\n          - type: findings-clear\n            config: { artifact: plan-review, blocking: [critical, high] }\n          - type: human-approval\n            config: { id: plan-approval }\n      - name: rework\n        to: plan\n        gates:\n          - type: artifact-fresh\n            config: { artifact: plan-review, recordedThisCycle: true }\n          - type: findings-open\n            config: { artifact: plan-review, blocking: [critical, high] }\n      - name: revise\n        to: plan\n        manual: true\n        description: >-\n          A person sent the plan back without a blocking finding, to change\n          the plan itself and have it reviewed again. To act on non-blocking\n          findings during implement, approve instead. Manual, so it never\n          fires on its own.\n\n  - id: implement\n    projection: { status: in_progress }\n    description: Implement the plan and commit it.\n    work:\n      mode: interactive\n      skills: []\n      systemPrompt: |\n        Implement the plan. Commit the work, then record change-summary with\n        the full 40-character SHA of the commit to check and review. Do not\n        open a pull request. After a check or review sends the work back, fix\n        it, commit, and record change-summary again for the new commit.\n      context:\n        inject: [plan, plan-review]\n    artifacts:\n      - name: change-summary\n        schema:\n          type: object\n          required: [summary, commit, files]\n          properties:\n            summary: { type: string, minLength: 1 }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            files: { type: array, minItems: 1, items: { type: string } }\n    transitions:\n      - name: submit\n        to: verify\n        gates:\n          - type: artifact-exists\n            config: { artifact: change-summary }\n\n  - id: verify\n    projection: { status: in_progress }\n    description: >-\n      Run the checks on the change-summary commit and record checks, with one\n      result per check.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Check out commit {{commit}} and run the stage\'s command. Record checks\n        with that commit, the overall status, and one result per check (its\n        name, status and, when it failed, the output that shows why). Record\n        only what you ran and saw.\n      command: >-\n        the project\'s format, lint, type and test checks (replace this with\n        the real commands)\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n    evidence:\n      - name: checks\n        schema:\n          type: object\n          required: [commit, status, results]\n          properties:\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            status: { enum: [passed, failed] }\n            results:\n              type: array\n              minItems: 1\n              items:\n                type: object\n                required: [name, status]\n                additionalProperties: false\n                properties:\n                  name: { type: string, minLength: 1 }\n                  status: { enum: [passed, failed, skipped] }\n                  detail: { type: string }\n          $comment: An overall pass cannot contain a failed result.\n          if:\n            properties: { status: { const: passed } }\n          then:\n            properties:\n              results:\n                not:\n                  contains:\n                    properties: { status: { const: failed } }\n    transitions:\n      - name: passed\n        to: code-review\n        gates:\n          - type: evidence-recorded\n            config: { name: checks, requireField: { status: passed } }\n          - type: cel\n            config:\n              expr: >-\n                evidence["checks"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: checks must be for the change-summary commit\n      - name: failed\n        to: implement\n        gates:\n          - type: evidence-recorded\n            config: { name: checks, requireField: { status: failed } }\n\n  - id: code-review\n    projection: { status: in_progress }\n    description: >-\n      Adversarial review of the change. Open blocking findings send it back;\n      none lets it through.\n    work:\n      mode: dispatch\n      skills: [code-review]\n      systemPrompt: |\n        You are an adversarial reviewer. Review commit {{commit}}:\n        {{changeSummary}}\n        Check it against the plan.\n        Rate a finding critical or high only if the change would ship a\n        defect, lose data, break a stated rule, or make the declared checks\n        meaningless. Gaps in process, logistics or manual verification that\n        the automated checks already cover are medium at most. Judge the\n        change against the size of the change: do not ask for verification\n        machinery bigger than the change, and give the smallest adequate fix\n        for each finding. Report findings with severities, and do not soften\n        the severity of a real defect.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n        changeSummary: artifacts["change-summary"].payload.summary\n      context:\n        inject: [plan, change-summary]\n    artifacts:\n      - name: code-review\n        kind: findings\n        reviews: change-summary\n    transitions:\n      - name: accept\n        to: release\n        gates:\n          - type: artifact-fresh\n            config: { artifact: code-review, recordedThisCycle: true }\n          - type: findings-clear\n            config: { artifact: code-review, blocking: [critical, high] }\n          - type: human-approval\n            config: { id: release-approval }\n      - name: rework\n        to: implement\n        gates:\n          - type: artifact-fresh\n            config: { artifact: code-review, recordedThisCycle: true }\n          - type: findings-open\n            config: { artifact: code-review, blocking: [critical, high] }\n      - name: revise\n        to: implement\n        manual: true\n        description: >-\n          A person sent the change back without a blocking finding. Manual, so\n          it never fires on its own.\n\n  - id: release\n    projection: { status: in_progress }\n    description: Release the reviewed commit.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Release the reviewed commit, and record release with the commit that\n        shipped and where.\n    evidence:\n      - name: release\n        schema:\n          type: object\n          required: [commit, url]\n          properties:\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            url: { type: string, format: uri }\n    transitions:\n      - name: released\n        to: done\n        gates:\n          - type: evidence-recorded\n            config: { name: release }\n      - name: rework\n        to: implement\n        manual: true\n        description: The release was blocked; go back and change the work.\n\n  - id: done\n    terminal: true\n    projection: { status: shipped }\n\n  - id: abandoned\n    terminal: true\n    projection: { status: closed }\n\nglobalTransitions:\n  - name: abandon\n    to: abandoned\n    gates:\n      - type: human-approval\n        config: { id: abandon-confirmation }\n',
  "swamp-club-swamp-extensions":
    'schemaVersion: 1\nname: swamp-club-swamp-extensions\ndescription: |-\n  A real-world example: a swamp-club Lab issue in swamp-extensions, from\n  triage through verification, the pull request and release to the session\n  summary.\n\n  For reading, not for copying whole: it shows a full process with a\n  tracker, a verification workflow, attestation and pull requests, and it\n  depends on that repository (the agent-constraints/ conventions its prompts\n  cite, the verification/ workflows and its forge). To build one like it,\n  start from starter.yaml and borrow the stages you need.\n\n  Change first, if you copy it whole: the verify stage\'s workflow, the\n  pull-request command and the conventions the prompts cite.\n\n  This is the process swamp-extensions runs with @swamp/issue-lifecycle and\n  agent-constraints/verification-conventions.md, written as a gatorwalk\n  factory definition. A work item on it drives a Lab issue end to end through\n  the swamp-club adapter (@swamp/gatorwalk-factory/swamp-club), so the issue\n  reads the same as one issue-lifecycle drives. issue-lifecycle stays, and\n  drives every other issue: the adapter\'s claim refuses an issue it already\n  drives. swamp-club-swamp-extensions.md maps every phase, gate and human stop\n  onto this factory definition and lists what the format could not express.\n\n  The work item never talks to swamp-club itself. The adapter\'s publish\n  replays its journal to the issue: each stage\'s projection names the Lab\n  status and the lifecycle entries (issue-lifecycle\'s step names) its events\n  become, and the classification sets the issue type. attest and notify post\n  the attestation and the contributor\'s thank-you through the adapter.\n\n  People decide at: a bug that cannot be reproduced, plan approval, the\n  verification checklist, opening the pull request, what to do after a\n  failed pull request, completing the work early (issue-lifecycle\'s complete,\n  from attest or merge), and abandoning the work. Every exit past implement is\n  bound to the commit named in change-summary, the commit that was reviewed\n  and verified. Commits are full 40-character SHAs.\n\n  The CEL vocabulary is in extensions/models/_lib/engine/cel_context.ts. In CEL,\n  evidence["x"] is the latest record of x in the era from any stage, unlike\n  the evidence-recorded gate, which only accepts evidence from the current\n  stage and cycle. implement.submit and attest.attested depend on it.\n\nstages:\n  - id: triage\n    initial: true\n    maxCycles: 5\n    projection:\n      entries:\n        - on: enter\n          step: triage_started\n          emoji: "🔍"\n          summary: "Triage started"\n          status: open\n        - on: { record: classification }\n          match: { isRegression: true }\n          step: classified\n          emoji: "📋"\n          summary: "Classified as {{type}} (regression) ({{confidence}})"\n          status: triaged\n          setsType: type\n        - on: { record: classification }\n          match: { isRegression: false }\n          step: classified\n          emoji: "📋"\n          summary: "Classified as {{type}} ({{confidence}})"\n          status: triaged\n          setsType: type\n    description: >-\n      Classify the issue. A low-confidence classification carries the\n      questions for the person and stops here until it is recorded again with\n      their answers. A classification with a regression verdict, confirmed\n      or downgraded, waits for a person to approve regression-review. The\n      classification records the effective flag, as issue-lifecycle\'s triage\n      sends it: isRegression is true only with a confirmed verdict, so the\n      Lab\'s regression flag is set, cleared or left as the verdict says, and\n      the classified entry says "(regression)" only then. A bug goes to reproduction;\n      anything else to planning. There is one exit per type, named as\n      issue-lifecycle\'s classifications are; the confidence check is a gate of\n      its own, so a type mismatch on a sibling exit never shows its message.\n      maxCycles states the default of five entries as the process\'s choice\n      (see plan).\n    work:\n      mode: interactive\n      systemPrompt: |\n        Read the issue and the code it touches, following\n        agent-constraints/triage-conventions.md. Classify it as bug, feature,\n        platform or security. If you believe it is a regression, gather the\n        evidence for it, argue against it, reach a verdict, record it, and\n        show both sides and the verdict to the person, who approves\n        regression-review (confirmed or downgraded) before the bug moves on.\n        Always record isRegression: true only with a confirmed verdict, and\n        false otherwise, including with a downgraded verdict. Record\n        regressionIntroducedIn only with a confirmed verdict.\n        If you cannot classify it\n        confidently, record confidence low with your questions, and record the\n        classification again once the person has answered.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n    evidence:\n      - name: classification\n        schema:\n          type: object\n          required: [type, confidence, reasoning, isRegression]\n          additionalProperties: false\n          properties:\n            type: { enum: [bug, feature, platform, security] }\n            confidence: { enum: [high, medium, low] }\n            reasoning: { type: string, minLength: 1 }\n            clarifyingQuestions:\n              type: array\n              minItems: 1\n              items: { type: string, minLength: 1 }\n            isRegression: { type: boolean }\n            regressionEvidence: { type: string, minLength: 1 }\n            regressionCounterEvidence: { type: string, minLength: 1 }\n            regressionVerdict: { enum: [confirmed, downgraded] }\n            regressionVerdictReasoning: { type: string, minLength: 1 }\n            regressionIntroducedIn: { type: string, minLength: 1 }\n          allOf:\n            - if:\n                properties: { confidence: { const: low } }\n              then:\n                required: [clarifyingQuestions]\n            - $comment: >-\n                A regression claim is a bug with both sides of the argument\n                and a verdict.\n              if:\n                required: [regressionVerdict]\n              then:\n                required:\n                  - regressionEvidence\n                  - regressionCounterEvidence\n                  - regressionVerdictReasoning\n                properties: { type: { const: bug } }\n            - $comment: >-\n                isRegression is the effective flag, as issue-lifecycle\'s\n                triage computes it: true only with a confirmed verdict.\n              if:\n                required: [isRegression]\n                properties: { isRegression: { const: true } }\n              then:\n                required: [regressionVerdict]\n                properties: { regressionVerdict: { const: confirmed } }\n            - $comment: A confirmed claim is a regression.\n              if:\n                required: [regressionVerdict]\n                properties: { regressionVerdict: { const: confirmed } }\n              then:\n                properties: { isRegression: { const: true } }\n            - $comment: A downgraded claim is not a regression.\n              if:\n                required: [regressionVerdict]\n                properties: { regressionVerdict: { const: downgraded } }\n              then:\n                properties: { isRegression: { const: false } }\n            - $comment: Only a confirmed regression was introduced somewhere.\n              if:\n                required: [regressionIntroducedIn]\n              then:\n                required: [regressionVerdict]\n                properties: { regressionVerdict: { const: confirmed } }\n    transitions:\n      - name: bug\n        to: reproduce\n        gates:\n          - type: evidence-recorded\n            config: { name: classification, requireField: { type: bug } }\n          - type: evidence-recorded\n            config:\n              name: classification\n              match: { confidence: { enum: [high, medium] } }\n              message: >-\n                a low-confidence classification waits for the person\'s\n                answers; record it again once they have answered\n          - type: human-approval\n            description: >-\n              A person sees the regression evidence, the counter-argument and\n              the verdict before a regression claim goes on, whichever way the\n              verdict went. It keys on the verdict, not on isRegression, which\n              is false for a downgraded claim. The guard keeps when false, not\n              an error, before a classification exists or when it has no\n              verdict.\n            config:\n              id: regression-review\n              when: >-\n                "classification" in evidence &&\n                has(evidence.classification.payload.regressionVerdict)\n      - name: feature\n        to: plan\n        gates:\n          - type: evidence-recorded\n            config: { name: classification, requireField: { type: feature } }\n          - type: evidence-recorded\n            config:\n              name: classification\n              match: { confidence: { enum: [high, medium] } }\n              message: >-\n                a low-confidence classification waits for the person\'s\n                answers; record it again once they have answered\n      - name: platform\n        to: plan\n        gates:\n          - type: evidence-recorded\n            config: { name: classification, requireField: { type: platform } }\n          - type: evidence-recorded\n            config:\n              name: classification\n              match: { confidence: { enum: [high, medium] } }\n              message: >-\n                a low-confidence classification waits for the person\'s\n                answers; record it again once they have answered\n      - name: security\n        to: plan\n        gates:\n          - type: evidence-recorded\n            config: { name: classification, requireField: { type: security } }\n          - type: evidence-recorded\n            config:\n              name: classification\n              match: { confidence: { enum: [high, medium] } }\n              message: >-\n                a low-confidence classification waits for the person\'s\n                answers; record it again once they have answered\n\n  - id: reproduce\n    projection: { status: triaged }\n    description: >-\n      Reproduce the bug before planning a fix. A bug that cannot be\n      reproduced goes on to planning only with a person\'s approval.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Reproduce the bug as agent-constraints/triage-conventions.md\n        describes for its scope: a failing deno test for an extension, a\n        generator diff for codegen, the failing CI run for a publish. Record\n        the commands, what you observed verbatim, what was expected, the scope\n        the fix belongs in and the blast radius. If it does not reproduce,\n        say so and ask the person how to proceed.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      context:\n        inject: [classification]\n    evidence:\n      - name: reproduction\n        schema:\n          type: object\n          required: [reproduced, commands, observed, expected, fixScope]\n          additionalProperties: false\n          properties:\n            reproduced: { type: boolean }\n            commands:\n              type: array\n              minItems: 1\n              items: { type: string, minLength: 1 }\n            observed: { type: string, minLength: 1 }\n            expected: { type: string, minLength: 1 }\n            fixScope: { type: string, minLength: 1 }\n            blastRadius: { type: string, minLength: 1 }\n    transitions:\n      - name: reproduced\n        to: plan\n        gates:\n          - type: evidence-recorded\n            config: { name: reproduction, requireField: { reproduced: true } }\n      - name: not-reproduced\n        to: plan\n        gates:\n          - type: evidence-recorded\n            config: { name: reproduction, requireField: { reproduced: false } }\n          - type: human-approval\n            config: { id: proceed-unreproduced }\n      - name: reclassify\n        to: triage\n        manual: true\n        description: >-\n          The person declined to go on without a reproduction, or the issue\n          is not the bug it looked like. Manual, so it never fires on its own.\n\n  - id: plan\n    projection:\n      status: triaged\n      entries:\n        - on: { record: plan }\n          cycle: first\n          step: plan_generated\n          emoji: "📝"\n          summary: "Implementation plan generated (v1) — {{summary}}"\n          verbose: true\n        - on: { record: plan }\n          cycle: later\n          step: plan_revised\n          emoji: "🔄"\n          summary: "Plan revised — {{summary}}"\n          verbose: true\n    description: >-\n      Plan the change, following the repository\'s planning conventions. Five\n      plans before a person grants another round: triage, plan, implement and\n      pull-request state the default of 5 as the process\'s choice, so each\n      loop has a limit someone chose (swamp-club-swamp-extensions.md, "Cycle\n      limits").\n    maxCycles: 5\n    work:\n      mode: interactive\n      systemPrompt: |\n        Plan the change following agent-constraints/planning-conventions.md.\n        Name the files each step touches, the scope and blast radius, how it\n        will be tested, and the challenges you expect. After rework, address\n        every open critical and high finding of the last review.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      context:\n        inject: [classification]\n    artifacts:\n      - name: plan\n        schema:\n          type: object\n          required: [summary, scopeAnalysis, steps, testingStrategy]\n          additionalProperties: false\n          properties:\n            summary: { type: string, minLength: 1 }\n            scopeAnalysis: { type: string, minLength: 1 }\n            steps:\n              type: array\n              minItems: 1\n              items:\n                type: object\n                required: [order, description, files]\n                additionalProperties: false\n                properties:\n                  order: { type: integer, minimum: 1 }\n                  description: { type: string, minLength: 1 }\n                  files: { type: array, items: { type: string, minLength: 1 } }\n                  risks: { type: string, minLength: 1 }\n            testingStrategy: { type: string, minLength: 1 }\n            potentialChallenges:\n              type: array\n              items: { type: string, minLength: 1 }\n    transitions:\n      - name: submit\n        to: plan-review\n        gates:\n          - type: artifact-exists\n            config: { artifact: plan }\n\n  - id: plan-review\n    projection:\n      status: triaged\n      entries:\n        - on: { record: plan-review }\n          step: adversarial_review\n          emoji: "🔍"\n          summary: "Adversarial review of the plan"\n          verbose: true\n        - on: { approve: plan-approval }\n          step: plan_approved\n          emoji: "✅"\n          summary: "Plan approved — implementation starting"\n          status: in_progress\n          verbose: true\n    description: >-\n      Adversarial review of the current plan. Approval needs a fresh review\n      with no open critical or high findings and a person\'s sign-off; open\n      critical or high findings send the plan back, and so can the person.\n    work:\n      mode: dispatch\n      systemPrompt: |\n        You are an adversarial reviewer. Try to refute this plan:\n        {{planSummary}}\n        Challenge it on every dimension in\n        agent-constraints/adversarial-dimensions.md and verify each step\n        against the code. Report findings with a severity and the dimension\n        as category; do not soften them.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        planSummary: artifacts["plan"].payload.summary\n      context:\n        inject: [plan]\n    artifacts:\n      - name: plan-review\n        kind: findings\n        reviews: plan\n        schema:\n          type: object\n          properties:\n            findings:\n              type: array\n              items: { type: object, required: [category] }\n    transitions:\n      - name: approve\n        to: implement\n        gates:\n          - type: artifact-fresh\n            config: { artifact: plan-review, recordedThisCycle: true }\n          - type: findings-clear\n            config: { artifact: plan-review, blocking: [critical, high] }\n          - type: human-approval\n            config: { id: plan-approval }\n      - name: rework\n        to: plan\n        gates:\n          - type: artifact-fresh\n            config: { artifact: plan-review, recordedThisCycle: true }\n          - type: cel\n            config:\n              expr: >-\n                "plan-review" in artifacts &&\n                artifacts["plan-review"].payload.findings.exists(f,\n                (f.severity == "critical" || f.severity == "high") &&\n                !(has(f.resolved) && f.resolved))\n              message: rework needs an open critical or high finding\n      - name: revise\n        to: plan\n        manual: true\n        description: >-\n          The person has feedback on the plan, or declined it without a\n          blocking finding. Manual, so it never fires on its own.\n\n  - id: implement\n    projection:\n      status: in_progress\n      entries:\n        - on: enter\n          step: implementation_started\n          emoji: "🚀"\n          summary: "Implementation started"\n    description: >-\n      Implement the approved plan and commit it. Each pass through\n      verification needs a new commit; recheck re-runs it on the same one.\n      Five commits through verification before a person grants another round\n      (see plan).\n    maxCycles: 5\n    work:\n      mode: interactive\n      systemPrompt: |\n        Implement the approved plan following\n        agent-constraints/implementation-conventions.md. Commit the work, with\n        the co-author trailer in the original commit, then record\n        change-summary with the full SHA and the branch. After rework, record\n        it again for the new commit.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      context:\n        inject: [plan, plan-review]\n    artifacts:\n      - name: change-summary\n        schema:\n          type: object\n          required: [summary, commit, branch, files]\n          additionalProperties: false\n          properties:\n            summary: { type: string, minLength: 1 }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            branch: { type: string, pattern: "^[A-Za-z0-9._/-]+$" }\n            files: { type: array, minItems: 1, items: { type: string } }\n    transitions:\n      - name: submit\n        to: conformance-review\n        gates:\n          - type: artifact-exists\n            config: { artifact: change-summary }\n          - type: cel\n            config:\n              expr: >-\n                !("verification" in evidence) ||\n                evidence["verification"].payload.commit !=\n                artifacts["change-summary"].payload.commit\n              message: >-\n                change-summary still names the commit already verified; record\n                it for the new commit\n      - name: recheck\n        to: verify\n        manual: true\n        description: >-\n          Verify the same commit again, for a failure that was not the code\'s\n          (a flaky test, a review provider error). A person decides. Only for\n          the commit verification already ran on: a new commit goes through\n          conformance-review first.\n        gates:\n          - type: cel\n            config:\n              expr: >-\n                "verification" in evidence &&\n                "change-summary" in artifacts &&\n                evidence["verification"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: >-\n                recheck re-verifies the commit verification already ran on; a\n                new commit goes through submit\n\n  - id: conformance-review\n    projection:\n      status: in_progress\n      entries:\n        - on: { record: conformance }\n          step: code_conformance_review\n          emoji: "🔍"\n          summary: "Code conformance review"\n          verbose: true\n    description: >-\n      Compare the committed code with the approved plan, step by step. Every\n      step not implemented as planned needs a justification; recording the\n      review again with them is how deviations are justified.\n    work:\n      mode: dispatch\n      systemPrompt: |\n        Compare commit {{commit}} with the approved plan. Fetch origin main,\n        then read git diff origin/main...{{commit}}. Check each plan step\n        against the diff and give it a status: implemented, deviated,\n        partially_implemented or missing. Add a step numbered 100 or more,\n        with status added, for each change no plan step covers. Justify\n        every step not implemented as planned, and judge the code against\n        agent-constraints/code-conformance-dimensions.md.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n      context:\n        inject: [plan, change-summary]\n    artifacts:\n      - name: conformance\n        reviews: change-summary\n        schema:\n          type: object\n          required: [steps]\n          additionalProperties: false\n          properties:\n            steps:\n              type: array\n              minItems: 1\n              items:\n                type: object\n                required: [order, status, description]\n                additionalProperties: false\n                properties:\n                  order: { type: integer, minimum: 1 }\n                  status:\n                    enum:\n                      - implemented\n                      - deviated\n                      - partially_implemented\n                      - missing\n                      - added\n                  description: { type: string, minLength: 1 }\n                  justification: { type: string, minLength: 1 }\n    transitions:\n      - name: conforms\n        to: verify\n        gates:\n          - type: artifact-fresh\n            config: { artifact: conformance, recordedThisCycle: true }\n          - type: cel\n            config:\n              expr: >-\n                artifacts["conformance"].payload.steps.all(s,\n                s.status == "implemented" || has(s.justification))\n              message: >-\n                every step not implemented as planned needs a justification\n      - name: rework\n        to: implement\n        manual: true\n        description: >-\n          The code has to change to match the plan. A person decides.\n\n  - id: verify\n    projection:\n      status: in_progress\n      entries:\n        - on: enter\n          step: verification_started\n          emoji: "🔍"\n          summary: "Verification started"\n        - on: { record: verification }\n          match: { status: succeeded }\n          step: verification_passed\n          emoji: "✅"\n          summary: "Verification passed for {{commit}}"\n        - on: { record: verification }\n          match: { status: failed }\n          step: verification_failed\n          emoji: "❌"\n          summary: "Verification failed for {{commit}}"\n    description: >-\n      The verify workflow at the change-summary commit: verify-build and\n      verify-reviews run concurrently as nested runs of one wrapper, and are\n      judged together. verify-build runs every check in\n      verification/checks.yaml for the directories the change touches, the\n      audits, codegen idempotency and the upgrade gate; verify-reviews runs\n      the agent reviews the change\'s paths call for. The wrapper fails if\n      either fails, and waits for both. A person then sees the combined\n      checklist of both runs and confirms it before the attestation is\n      posted. A factory definition is in one stage at a time, so this is how the\n      two run in parallel; see DESIGN.md, "Parallel work inside one stage".\n    work:\n      mode: workflow\n      workflow: { name: verify }\n      command: >-\n        SWAMP_WORKFLOWS_DIR=<absolute path to the checkout>/verification\n        swamp workflow run verify --input commit={{commit}}\n        --input branch={{branch}} (from a worktree, add --repo-dir with the\n        main checkout). The child run ids are each step\'s output.runId in the\n        wrapper\'s run record; a failed child\'s is found with swamp workflow\n        history search verify-build (or verify-reviews).\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n        branch: artifacts["change-summary"].payload.branch\n      inputsSchema:\n        type: object\n        required: [commit, branch]\n        properties:\n          commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n          branch: { type: string, pattern: "^[A-Za-z0-9._/-]+$" }\n      resultEvidence: verification\n    evidence:\n      - name: verification\n        description: >-\n          The wrapper run\'s outcome and each child\'s. status and runId are the\n          wrapper run\'s: succeeded only when both children succeeded. A\n          child\'s run id is missing only when it never started.\n        schema:\n          type: object\n          required: [status, runId, commit, buildStatus, reviewsStatus]\n          additionalProperties: false\n          properties:\n            status: { enum: [succeeded, failed] }\n            runId: { type: string, minLength: 1 }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            buildStatus: { enum: [succeeded, failed] }\n            buildRunId: { type: string, minLength: 1 }\n            reviewsStatus: { enum: [succeeded, failed] }\n            reviewsRunId: { type: string, minLength: 1 }\n            outputs: { type: object }\n    transitions:\n      - name: passed\n        to: attest\n        gates:\n          - type: evidence-recorded\n            config:\n              name: verification\n              requireField: { status: succeeded }\n          - type: cel\n            config:\n              expr: >-\n                evidence["verification"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: verification must have run on the change-summary commit\n          - type: cel\n            config:\n              expr: >-\n                evidence["verification"].payload.buildStatus == "succeeded" &&\n                evidence["verification"].payload.reviewsStatus == "succeeded"\n                && "buildRunId" in evidence["verification"].payload &&\n                "reviewsRunId" in evidence["verification"].payload\n              message: >-\n                both verify-build and verify-reviews must have succeeded, with\n                their run ids; status is the wrapper run\'s own, which fails\n                when either child does\n          - type: human-approval\n            config: { id: checklist-confirmed }\n      - name: failed\n        to: implement\n        gates:\n          - type: evidence-recorded\n            config: { name: verification, requireField: { status: failed } }\n      - name: revise\n        to: implement\n        manual: true\n        description: >-\n          The person did not confirm the checklist. Manual, so it never fires\n          on its own.\n\n  - id: attest\n    projection:\n      status: in_progress\n      entries:\n        - on: { record: attestation }\n          step: attestation_posted\n          emoji: "📜"\n          summary: "Verification attestation posted to swamp-club"\n    description: >-\n      Build the attestation from the two child runs of verify, post it through\n      the swamp-club adapter\'s post_attestation, and record the id it returns.\n      Interactive, not mode method: the attestation is built during the stage,\n      and a method call takes only inputs known before it. The pull request\n      opens only once a person says so.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Build the attestation with deno task build-attestation from run\n        {{buildRun}} and run {{reviewsRun}} at commit {{commit}}. Post it with\n        the swamp-club adapter\'s post_attestation (swamp model method run\n        <adapter> post_attestation --input attestation=<the JSON>) and record\n        the id it logs. Never change the commit after this: the attestation is\n        bound to it. Ask the person before opening the pull request.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n        buildRun: evidence["verification"].payload.buildRunId\n        reviewsRun: evidence["verification"].payload.reviewsRunId\n    evidence:\n      - name: attestation\n        schema:\n          type: object\n          required: [attestationId, commit, buildRunId, reviewsRunId]\n          additionalProperties: false\n          properties:\n            attestationId: { type: string, minLength: 1 }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            buildRunId: { type: string, minLength: 1 }\n            reviewsRunId: { type: string, minLength: 1 }\n    transitions:\n      - name: attested\n        to: pull-request\n        gates:\n          - type: evidence-recorded\n            config: { name: attestation }\n          - type: cel\n            config:\n              expr: >-\n                evidence["attestation"].payload.commit ==\n                artifacts["change-summary"].payload.commit &&\n                evidence["attestation"].payload.buildRunId ==\n                evidence["verification"].payload.buildRunId &&\n                evidence["attestation"].payload.reviewsRunId ==\n                evidence["verification"].payload.reviewsRunId\n              message: >-\n                the attestation must be built from this commit\'s verify-build\n                and verify-reviews runs\n          - type: human-approval\n            config: { id: open-pr }\n      - name: revise\n        to: implement\n        manual: true\n        description: >-\n          The person did not want the pull request opened for this commit.\n          Manual, so it never fires on its own.\n      - name: complete\n        to: notify\n        manual: true\n        description: >-\n          issue-lifecycle\'s complete from implementing: the work is done\n          without a pull request. A person decides. issue-lifecycle requires\n          conformance and verification to be clear, which here they are once\n          the checklist is confirmed; the gates check them again at the\n          change-summary commit.\n        gates:\n          - type: cel\n            config:\n              expr: >-\n                "conformance" in artifacts &&\n                artifacts["conformance"].payload.steps.all(s,\n                s.status == "implemented" || has(s.justification))\n              message: >-\n                complete needs a conformance review in which every step not\n                implemented as planned has a justification\n          - type: cel\n            config:\n              expr: >-\n                "verification" in evidence && "change-summary" in artifacts &&\n                evidence["verification"].payload.status == "succeeded" &&\n                evidence["verification"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: >-\n                complete needs verification to have passed on the\n                change-summary commit\n          - type: cel\n            config:\n              expr: >-\n                "verification" in evidence &&\n                evidence["verification"].payload.buildStatus == "succeeded" &&\n                evidence["verification"].payload.reviewsStatus == "succeeded"\n                && "buildRunId" in evidence["verification"].payload &&\n                "reviewsRunId" in evidence["verification"].payload\n              message: >-\n                complete needs both verify-build and verify-reviews to have\n                succeeded, with their run ids\n\n  - id: pull-request\n    projection:\n      status: in_progress\n      entries:\n        - on: { record: pull-request }\n          step: pr_linked\n          emoji: "🔗"\n          summary: "PR linked: {{url}}"\n    description: >-\n      Open the pull request for the attested commit. Four replacement pull\n      requests before a person grants another (see plan).\n    maxCycles: 5\n    work:\n      mode: interactive\n      systemPrompt: |\n        Open the pull request for commit {{commit}} with\n        fj -H git.swamp-club.com pr create, then record its url.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        commit: artifacts["change-summary"].payload.commit\n    evidence:\n      - name: pull-request\n        schema:\n          type: object\n          required: [url, commit]\n          additionalProperties: false\n          properties:\n            url: { type: string, format: uri }\n            commit: { type: string, pattern: "^[0-9a-f]{40}$" }\n    transitions:\n      - name: opened\n        to: merge\n        gates:\n          - type: evidence-recorded\n            config: { name: pull-request }\n          - type: cel\n            config:\n              expr: >-\n                evidence["pull-request"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: the pull request must be for the attested commit\n\n  - id: merge\n    projection:\n      status: in_progress\n      entries:\n        - on: { record: merge }\n          match: { status: merged }\n          step: pr_merged\n          emoji: "🎉"\n          summary: "PR merged — awaiting release"\n        - on: { record: merge }\n          match: { status: failed }\n          step: pr_failed\n          emoji: "❌"\n          summary: "PR failed: {{reason}}"\n    description: >-\n      Wait for CI and the merge. The outcome is reported no sooner than three\n      minutes after the pull request was recorded, to give CI time to run. A\n      failed pull request goes to a new pull request or back to implement; a\n      person decides.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Check the pull request {{url}}. When it has merged, record the merge\n        commit. If it failed (CI, or it was closed), record why.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        url: evidence["pull-request"].payload.url\n    evidence:\n      - name: merge\n        schema:\n          type: object\n          required: [status]\n          additionalProperties: false\n          properties:\n            status: { enum: [merged, failed] }\n            mergeCommit: { type: string, pattern: "^[0-9a-f]{40}$" }\n            reason: { type: string, minLength: 1 }\n          allOf:\n            - if:\n                properties: { status: { const: merged } }\n              then:\n                required: [mergeCommit]\n            - if:\n                properties: { status: { const: failed } }\n              then:\n                required: [reason]\n    transitions:\n      - name: merged\n        to: release\n        gates:\n          - type: evidence-recorded\n            config: { name: merge, requireField: { status: merged } }\n          - type: cooldown\n            config: { afterEvidence: pull-request, seconds: 180 }\n      - name: new-pr\n        to: pull-request\n        manual: true\n        description: >-\n          Open a new pull request for the same commit, for a failure that was\n          not the code\'s.\n        gates:\n          - type: evidence-recorded\n            config: { name: merge, requireField: { status: failed } }\n          - type: cooldown\n            config: { afterEvidence: pull-request, seconds: 180 }\n      - name: rework\n        to: implement\n        manual: true\n        description: The pull request failed because of the code; change it.\n        gates:\n          - type: evidence-recorded\n            config: { name: merge, requireField: { status: failed } }\n          - type: cooldown\n            config: { afterEvidence: pull-request, seconds: 180 }\n      - name: complete\n        to: notify\n        manual: true\n        description: >-\n          issue-lifecycle\'s complete from pr_open: the pull request is open\n          and a person decides the work is done. Not once a merge outcome is\n          recorded for it: issue-lifecycle has left pr_open by then (a merged\n          one goes on to release, a failed one to new-pr or rework). No\n          cooldown, as issue-lifecycle\'s complete checks no pull request\n          status.\n        gates:\n          - type: cel\n            config:\n              expr: >-\n                !("merge" in evidence) || evidence["merge"].stage != "merge"\n                || evidence["merge"].cycle != stage.cycle\n              message: >-\n                complete is for an open pull request; a merge outcome is\n                already recorded for this one\n          - type: cel\n            config:\n              expr: >-\n                "conformance" in artifacts &&\n                artifacts["conformance"].payload.steps.all(s,\n                s.status == "implemented" || has(s.justification))\n              message: >-\n                complete needs a conformance review in which every step not\n                implemented as planned has a justification\n          - type: cel\n            config:\n              expr: >-\n                "verification" in evidence && "change-summary" in artifacts &&\n                evidence["verification"].payload.status == "succeeded" &&\n                evidence["verification"].payload.commit ==\n                artifacts["change-summary"].payload.commit\n              message: >-\n                complete needs verification to have passed on the\n                change-summary commit\n          - type: cel\n            config:\n              expr: >-\n                "verification" in evidence &&\n                evidence["verification"].payload.buildStatus == "succeeded" &&\n                evidence["verification"].payload.reviewsStatus == "succeeded"\n                && "buildRunId" in evidence["verification"].payload &&\n                "reviewsRunId" in evidence["verification"].payload\n              message: >-\n                complete needs both verify-build and verify-reviews to have\n                succeeded, with their run ids\n\n  - id: release\n    projection:\n      status: in_progress\n      entries:\n        - on: { record: release }\n          match: { outcome: shipped }\n          step: shipped\n          emoji: "🚀"\n          summary: "Shipped"\n          status: shipped\n        - on: { record: release }\n          match: { outcome: completed }\n          step: complete\n          emoji: "✅"\n          summary: "Complete"\n          status: shipped\n    description: >-\n      Check that the change was released: CI publishes an extension whose\n      manifest changed on main. completed is the fallback when there is no\n      release build to check.\n    work:\n      mode: interactive\n      systemPrompt: |\n        Check the release build for merge commit {{mergeCommit}}. Record\n        shipped with the published version once it is in the registry, or\n        completed when nothing was published.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        mergeCommit: evidence["merge"].payload.mergeCommit\n    evidence:\n      - name: release\n        schema:\n          type: object\n          required: [outcome]\n          additionalProperties: false\n          properties:\n            outcome: { enum: [shipped, completed] }\n            version:\n              type: string\n              pattern: "^[0-9]{4}\\\\.[0-9]{2}\\\\.[0-9]{2}\\\\.[0-9]+$"\n            detail: { type: string, minLength: 1 }\n    transitions:\n      - name: released\n        to: notify\n        gates:\n          - type: evidence-recorded\n            config: { name: release }\n\n  - id: notify\n    projection:\n      status: shipped\n      entries:\n        - on: { record: notification }\n          match: { action: posted }\n          step: contributor_notified\n          emoji: "🙏"\n          summary: "Thanked @{{author}}"\n        - on: { record: notification }\n          match: { action: skipped }\n          step: notification_skipped\n          emoji: "⏭️"\n          summary: "Contributor notification skipped: {{reason}}"\n    description: >-\n      Thank the issue\'s author, unless they are on the swamp-club team, through\n      the swamp-club adapter\'s thank_author. Interactive, not mode method: when\n      the team lookup fails, a person chooses to re-run, force or skip, as\n      with issue-lifecycle.\n    work:\n      mode: interactive\n      description: >-\n        The prUrl binding is only the pull request for the change-summary\n        commit: attest.complete reaches notify with none, or with one from an\n        earlier, failed round.\n      systemPrompt: |\n        Run the swamp-club adapter\'s thank_author with the issue, summary\n        and prUrl values you are given; leave prUrl out when it is null (no\n        pull request for this commit, after complete from attest). The\n        summary is free text, so never\n        paste it into a shell line: write the three as a JSON object to a\n        file with your file tool and run swamp model method run <adapter>\n        thank_author --input-file <that file> --log. It checks the author\n        against the team roster, never GitHub, and posts the thank-you only\n        to an author outside the team, and never twice: a re-run finds it\n        already posted. Record its action, author and reason. If the lookup\n        fails it posts nothing: ask the person whether to re-run it, run it\n        with force set to true, or skip, and record skipped with their\n        reason.\n\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      bindings:\n        issue: item.externalRefs["swamp-club"]\n        summary: artifacts["plan"].payload.summary\n        prUrl: >-\n          "pull-request" in evidence && "change-summary" in artifacts &&\n          evidence["pull-request"].payload.commit ==\n          artifacts["change-summary"].payload.commit\n          ? evidence["pull-request"].payload.url : null\n    evidence:\n      - name: notification\n        schema:\n          type: object\n          required: [action, author, reason]\n          additionalProperties: false\n          properties:\n            action: { enum: [posted, skipped] }\n            author: { type: string, minLength: 1 }\n            reason: { type: string, minLength: 1 }\n    transitions:\n      - name: notified\n        to: summary\n        gates:\n          - type: evidence-recorded\n            config: { name: notification }\n\n  - id: summary\n    projection:\n      status: shipped\n      entries:\n        - on: { record: summary }\n          match: { outcomeMet: true }\n          step: session_summarized\n          emoji: "📝"\n          summary: "Outcome met: {{deliveredOutcome}}"\n        - on: { record: summary }\n          match: { outcomeMet: false }\n          step: session_summarized\n          emoji: "📝"\n          summary: "Outcome NOT met: {{deliveredOutcome}}"\n    description: >-\n      Restate the original problem and the delivered outcome, and say whether\n      the outcome met the problem.\n    work:\n      mode: interactive\n      systemPrompt: |\n        gatorwalk drives this issue: do not use the issue-lifecycle skill or\n        run any @swamp/issue-lifecycle method, even when a request would\n        trigger it.\n      context:\n        inject: [plan, change-summary]\n    artifacts:\n      - name: summary\n        schema:\n          type: object\n          required: [originalProblem, deliveredOutcome, outcomeMet]\n          additionalProperties: false\n          properties:\n            originalProblem: { type: string, minLength: 1 }\n            deliveredOutcome: { type: string, minLength: 1 }\n            outcomeMet: { type: boolean }\n    transitions:\n      - name: finish\n        to: done\n        gates:\n          - type: artifact-exists\n            config: { artifact: summary }\n\n  - id: done\n    terminal: true\n    projection: { status: shipped }\n\n  - id: abandoned\n    terminal: true\n    projection:\n      status: closed\n      entries:\n        - on: enter\n          step: abandoned\n          emoji: "🛑"\n          summary: "Abandoned"\n\nglobalTransitions:\n  - name: abandon\n    to: abandoned\n    gates:\n      - type: human-approval\n        config: { id: abandon-confirmation }\n',
};
